mapper.select:
SELECT o.id, o.order_no AS orderNo, u1.nickname AS buyerNickname, o.buyer_id AS buyerId, u1.user_pic AS buyerPic, o.seller_id AS sellerId, u2.nickname AS sellerNickname, o.address_id AS addressId, u2.user_pic AS sellerPic, o.goods_id AS goodsId, o.goods_name AS goodsName, o.goods_pic AS goodsPic, o.goods_price AS goodsPrice, o.goods_num AS goodsNum, o.total_amount AS totalAmount, o.order_status AS orderStatus, o.pay_type AS payType, o.refund_status AS refundStatus, o.refund_amount AS refundAmount, o.refund_reason AS refundReason, o.create_time AS createTime, o.update_time AS updateTime FROM order_info o LEFT JOIN user u1 ON o.buyer_id = u1.id LEFT JOIN user u2 ON o.seller_id = u2.id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.buyer_id = #{buyerId}
AND o.seller_id = #{sellerId}
AND o.goods_id = #{goodsId}
AND o.order_status = #{orderStatus}
AND o.refund_status = #{refundStatus}
ORDER BY o.create_time DESC
